function profileAvatar(o){const src=o.profilFotoUrl||o.fotograf||o.foto||o.photoURL||o.profilFoto||'';const initials=((o.ad||'?')[0]+(o.soyad||'')[0]).toLocaleUpperCase('tr');return src?`<img src="${esc(src)}" alt="" style="width:100%;height:100%;object-fit:cover;border-radius:inherit">`:esc(initials)}
