function teacherCard(o){const bd=todayLessons(o.id),nb=teacherDuty(o.id),kl=teacherClub(o.id),rh=teacherGuide(o.id),hafta=teacherLessons(o.id).length,ilk=bd[0];return `<article class="ogm-card" data-ogretmen-id="${esc(o.id)}"><div class="ogm-card-top">${teacherAvatar(o)}<div class="ogm-name"><b>${esc(fullName(o))}</b><span>${esc(o.brans||o.unvan||'Öğretmen')}</span></div><button type="button" class="ogm-more" data-exact-teacher-detail="${esc(o.id)}" aria-label="Detay">›</button></div><div class="ogm-tags">${teacherOnLeave(o.id)?'<span class="ogm-tag red">İzinli</span>':''}${bd.length?`<span class="ogm-tag">Bugün ${bd.length} ders</span>`:'<span class="ogm-tag">Bugün dersi yok</span>'}${nb.length?'<span class="ogm-tag warn">Nöbet kaydı</span>':''}</div><div class="ogm-info">${ilk?`<div class="ogm-info-row"><span>📚</span><span>Sıradaki: ${esc(ilk.sinif||'—')} · ${esc(ilk.ders||'—')} · ${esc(ilk.saat||'—')}. ders</span></div>`:`<div class="ogm-info-row"><span>📚</span><span>Haftalık ${hafta} ders saati</span></div>`}${rh?`<div class="ogm-info-row"><span>🏫</span><span>Sınıf danışmanlığı: ${esc(rh.ad||rh.sinif||'—')}</span></div>`:''}${kl?`<div class="ogm-info-row"><span>👥</span><span>Kulüp: ${esc(kl.ad||kl.kulupAdi||'—')}</span></div>`:''}${o.telefon?`<div class="ogm-info-row"><span>☎</span><span>${esc(o.telefon)}</span></div>`:''}</div><div class="ogm-actions"><button type="button" class="ogm-action primary" data-exact-teacher-detail="${esc(o.id)}">Profili Gör</button>${can('people.teachers','edit')?`<button type="button" class="ogm-action" data-exact-teacher-edit="${esc(o.id)}">Düzenle</button>`:''}</div></article>`}
function teacherView(){let list=teachers().filter(o=>{const hay=norm(`${fullName(o)} ${o.brans||''} ${o.unvan||''}`);return(!query||hay.includes(norm(query)))&&(!branch||o.brans===branch)}).sort((a,b)=>fullName(a).localeCompare(fullName(b),'tr'));const branches=[...new Set(teachers().map(o=>o.brans).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'tr')),nobetSay=teachers().filter(o=>teacherDuty(o.id).length).length;return `<div class="ogm-shell"><div class="ogm-head"><div class="ogm-title"><small>Koruk Asistan · Personel Merkezi</small><h2>Öğretmenler</h2><p>Program, nöbet ve sorumluluklar tek ekranda.</p></div><div class="ogm-head-actions">${can('people.teachers','edit')?'<button class="ogm-import" data-exact-teacher-excel>Excel</button><button class="ogm-add" data-exact-teacher-add>+ Öğretmen</button>':''}</div></div><div class="ogm-stats"><div class="ogm-stat"><b>${teachers().length}</b><span>Öğretmen</span></div><div class="ogm-stat"><b>${branches.length}</b><span>Branş</span></div><div class="ogm-stat"><b>${nobetSay}</b><span>Nöbet Kaydı</span></div></div><div class="ogm-tools"><label class="ogm-search"><span>⌕</span><input data-exact-search value="${esc(query)}" placeholder="Öğretmen veya branş ara…"></label><select data-exact-branch class="ogm-filter"><option value="">Tüm branşlar</option>${branches.map(b=>`<option value="${esc(b)}" ${branch===b?'selected':''}>${esc(b)}</option>`).join('')}</select></div><div class="ogm-grid">${list.length?list.map(teacherCard).join(''):'<div class="ogm-empty">Arama ölçütlerine uygun öğretmen bulunamadı.</div>'}</div></div>`}
