function classView(){const list=classRows(),total=classes().reduce((n,s)=>n+students().filter(v=>v.sinifId===s.id).length,0),imports=can('people.students.edit','edit');return `<div class="classic-page"><div class="classic-page-head"><div><h2>Sınıflar</h2><p>${classes().length} sınıf · ${total} öğrenci</p></div><div class="classic-actions">${imports?'<button class="classic-btn" data-exact-class-excel-all>📥 Öğrenci Listesi Excel</button><button class="classic-btn" data-exact-class-eokul-all>📋 e-Okul Sınıf Listesi</button>':''}${can('people.classes','edit')?'<button class="classic-btn primary" data-exact-class-add>+ Yeni Sınıf</button>':''}</div></div><div class="classic-card"><div class="classic-toolbar"><input data-exact-search value="${esc(query)}" placeholder="Sınıf adına göre ara..."><span class="classic-summary">${classes().length} sınıf · ${total} öğrenci</span></div><div class="classic-table-wrap"><table class="classic-table"><thead><tr><th>Sınıf</th><th>Seviye</th><th>Sınıf Öğretmeni</th><th>Öğrenci</th><th>Kız</th><th>Erkek</th><th>Derslik</th><th></th></tr></thead><tbody>${list.length?list.map(s=>{const st=students().filter(v=>v.sinifId===s.id),g=st.filter(v=>v.cinsiyet==='Kız').length,b=st.filter(v=>v.cinsiyet==='Erkek').length;return `<tr data-exact-class-detail="${esc(s.id)}"><td><strong>${esc(s.ad||'')}</strong></td><td>${esc(s.seviye||'—')}</td><td>${esc(fullName(classTeacher(s)))}</td><td>${st.length}</td><td>${g}</td><td>${b}</td><td>${esc(s.derslik||'—')}</td><td>${can('people.classes','edit')?`<button class="classic-btn" data-exact-class-edit="${esc(s.id)}">Düzenle</button>`:''}</td></tr>`}).join(''):'<tr><td colspan="8">Henüz sınıf eklenmedi.</td></tr>'}</tbody></table></div></div></div>`}
function studentPhones(v){return [v.telefon1||v.telefon,v.telefon2,v.telefon3].filter(Boolean)}
function studentPhoneLines(v){return [1,2,3].map(i=>{const phone=i===1?(v.telefon1||v.telefon):v[`telefon${i}`],rel=v[`yakinlik${i}`]||(i===1?v.yakinlik:'');return phone?`${rel?rel+': ':''}${phone}`:''}).filter(Boolean)}
function studentRow(v,sinifAdi){const phones=studentPhones(v);return `<div class="detay-row student-row" data-exact-student-detail="${esc(v.id)}"><span><strong>${esc(v.ogrenciAdi||'—')}</strong>${v.ogrenciNo?` <span class="detay-row-muted">No:${esc(v.ogrenciNo)}</span>`:''}${v.cinsiyet?` <span class="badge ${v.cinsiyet==='Kız'?'badge-rose':'badge-blue'}">${esc(v.cinsiyet)}</span>`:''}${v.servisAdi?` <span class="badge badge-amber">🚌 ${esc(v.servisAdi)}</span>`:''}${v.kulupAdi?` <span class="badge badge-sage">🎗️ ${esc(v.kulupAdi)}</span>`:''}<br><span class="detay-row-muted">${esc(sinifAdi||'—')} · ${esc(v.veliAdi||'—')}</span>${phones.length?`<br><span class="detay-row-muted">📞 ${esc(phones.join(' · '))}</span>`:''}</span><span style="color:var(--ogm-muted);font-size:18px">›</span></div>`}
