function studentView(){let list=students().filter(v=>(!studentClass||v.sinifId===studentClass)&&(!studentGender||v.cinsiyet===studentGender)&&(!query||norm(`${v.ogrenciAdi||''} ${v.veliAdi||''} ${v.ogrenciNo||''} ${className(v.sinifId)} ${studentPhones(v).join(' ')}`).includes(norm(query)))).sort((a,b)=>(a.ogrenciAdi||'').localeCompare(b.ogrenciAdi||'','tr'));const groups=new Map();for(const v of list){const n=className(v.sinifId);if(!groups.has(n))groups.set(n,[]);groups.get(n).push(v)}return `<div class="classic-page"><div class="classic-page-head"><div><h2>Öğrenciler</h2><p>Öğrenci ve veli kayıtları.</p></div><div class="classic-actions">${can('people.students.edit','edit')?'<button class="classic-btn primary" data-exact-student-add>+ Öğrenci Ekle</button>':''}</div></div><div class="classic-toolbar"><input data-exact-search value="${esc(query)}" placeholder="Öğrenci, veli veya telefon ara…"><select data-exact-student-class><option value="">Tüm sınıflar</option>${classes().slice().sort((a,b)=>String(a.ad||'').localeCompare(String(b.ad||''),'tr',{numeric:true})).map(s=>`<option value="${esc(s.id)}" ${studentClass===s.id?'selected':''}>${esc(s.ad)}</option>`).join('')}</select><select data-exact-student-gender><option value="">Tüm cinsiyetler</option><option value="Kız" ${studentGender==='Kız'?'selected':''}>Kız</option><option value="Erkek" ${studentGender==='Erkek'?'selected':''}>Erkek</option></select><span class="classic-summary">${list.length} öğrenci</span></div>${list.length?[...groups.entries()].sort(([a],[b])=>a.localeCompare(b,'tr',{numeric:true})).map(([name,rows])=>`<section class="classic-card"><div class="student-group-title"><h3>🏫 ${esc(name)}</h3><span class="detay-row-muted">(${rows.length} öğrenci)</span></div>${rows.map(v=>studentRow(v,name)).join('')}</section>`).join(''):'<div class="classic-card">Kayıt bulunamadı.</div>'}</div>`}
function render(){if(!root||global.AppStore?.get?.('ui.route')!=='people')return;if(delegated){canonical.render?.();return}root.innerHTML=`<section data-people-classic>${page==='classes'?classView():teacherView()}</section>`;bind();global.PermissionService?.apply?.(root)}
function closeDetail(){detail?.remove();detail=null;document.body.classList.remove('modal-open')}
