function docSummary(type,k){if(type==='sosyalKulupler')return k.ad||k.kulupAdi||'Sosyal kulüp';if(type==='belirliGunler')return [k.ad||k.baslik,k.tarihBaslangic||k.tarih].filter(Boolean).join(' · ')||'Belirli gün / hafta';if(type==='maarifRapor')return [k.ders||k.rapor,k.sinif].filter(Boolean).join(' · ')||'Maarif raporu';if(type==='bepPlani')return [k.sinif,k.ders].filter(Boolean).join(' · ')||k.ad||'Yıllık / BEP planı';if(type==='zumre')return [k.brans,k.sinif].filter(Boolean).join(' · ')||k.ad||'Zümre';if(type==='sok')return [k.sinif,k.brans].filter(Boolean).join(' · ')||k.ad||'ŞÖK';if(type==='rehberlik')return [k.sinif,k.danisman].filter(Boolean).join(' · ')||k.ad||'Rehberlik';return k.ad||k.baslik||'Kayıt'}
