function reportRelated(type,o){const out=[...relatedRows(type,o.id)],seen=new Set(out.map(x=>x.id).filter(Boolean)),name=norm(fullName(o));for(const x of arr(type)){if(x.id&&seen.has(x.id))continue;const names=[x.ogretmen,x.danisman,x.gorevliOgretmen,x.sorumluOgretmen].filter(Boolean).map(norm),many=[x.gorevliOgretmenler,x.ogretmenler].filter(Array.isArray).flat().map(norm);if(name&&(names.some(n=>n===name||n.includes(name))||many.some(n=>n===name||n===norm(o.id)))){out.push(x);if(x.id)seen.add(x.id)}}return out}
