function closeModal(){document.querySelector('[data-exact-people-modal]')?.remove()}
function modal(title,body,onSave,onDelete=null){closeModal();const ov=document.createElement('div');ov.className='classic-modal-backdrop';ov.dataset.exactPeopleModal='';ov.dataset.peopleClassic='';ov.innerHTML=`<form class="classic-modal"><div class="classic-modal-head"><h3>${esc(title)}</h3><button type="button" class="detail-close" data-exact-modal-close>×</button></div><div class="classic-modal-body">${body}</div><div class="classic-modal-actions">${onDelete?'<button type="button" class="ka-btn ka-btn--danger ka-btn--sm" data-exact-modal-delete>Sil</button><span class="ka-grow"></span>':''}<button type="button" class="classic-btn" data-exact-modal-close>Vazgeç</button><button type="submit" class="classic-btn primary">Kaydet</button></div></form>`;document.body.appendChild(ov);$$('[data-exact-modal-close]',ov).forEach(b=>b.onclick=closeModal);ov.addEventListener('click',e=>{if(e.target===ov)closeModal()});$('[data-exact-modal-delete]',ov)?.addEventListener('click',async()=>{try{const ok=await onDelete?.();if(ok===false)return;closeModal();closeDetail();render();global.toast?.('Silindi.')}catch(err){global.toast?.('Hata: '+(err?.message||err))}});$('form',ov).onsubmit=async e=>{e.preventDefault();try{await onSave(new FormData(e.currentTarget));closeModal();render();global.toast?.('Kaydedildi.')}catch(err){global.toast?.('Hata: '+(err?.message||err))}};return ov}
function teacherForm(id=''){const o=teachers().find(x=>x.id===id)||{},branches=[...new Set(teachers().map(x=>x.brans).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'tr'));modal(id?'Öğretmen Düzenle':'Yeni Öğretmen',`<div class="classic-form-row"><div class="classic-field"><label>Ad</label><input name="ad" value="${esc(o.ad||'')}" required></div><div class="classic-field"><label>Soyad</label><input name="soyad" value="${esc(o.soyad||'')}" required></div></div><div class="classic-field"><label>Ünvan</label><input name="unvan" value="${esc(o.unvan||'Öğretmen')}"></div><div class="classic-field"><label>Branş</label><select name="brans"><option value="">Seçiniz</option>${[...new Set([...branches,o.brans].filter(Boolean))].map(b=>`<option value="${esc(b)}" ${o.brans===b?'selected':''}>${esc(b)}</option>`).join('')}</select></div><div class="classic-form-row"><div class="classic-field"><label>Telefon</label><input name="telefon" value="${esc(o.telefon||'')}"></div><div class="classic-field"><label>E-posta</label><input name="eposta" value="${esc(o.eposta||o.email||'')}"></div></div><div class="classic-form-row"><div class="classic-field"><label>Derece</label><input name="derece" value="${esc(o.derece||'')}"></div><div class="classic-field"><label>Kademe</label><input name="kademeNo" value="${esc(o.kademeNo||'')}"></div></div><div class="classic-field"><label>Notlar</label><textarea name="notlar" rows="2">${esc(o.notlar||'')}</textarea></div>`,async fd=>{await global.OgretmenService.kaydet(id,{ad:String(fd.get('ad')||'').trim(),soyad:String(fd.get('soyad')||'').trim(),unvan:String(fd.get('unvan')||'').trim(),brans:String(fd.get('brans')||'').trim(),telefon:String(fd.get('telefon')||'').trim(),eposta:String(fd.get('eposta')||'').trim(),derece:String(fd.get('derece')||'').trim(),kademeNo:String(fd.get('kademeNo')||'').trim(),notlar:String(fd.get('notlar')||'').trim(),aktif:true})})}
