function openClassSeating(id){global.AppLoader?.setActiveModule?.('transport');global.AppLoader?.load?.('transport').then(()=>{global.TransportModule?.openPage?.('classSeats','Sınıf Oturma');requestAnimationFrame(()=>global.TransportModule?.openClassSeating?.(id))}).catch(()=>global.toast?.('Sınıf oturma planı açılamadı.'))}
