function bindDetail(scope){$$('[data-exact-teacher-edit]',scope).forEach(b=>b.onclick=()=>{const id=b.dataset.exactTeacherEdit;closeDetail();teacherForm(id)});$$('[data-exact-teacher-report]',scope).forEach(b=>b.onclick=()=>{const o=teachers().find(x=>x.id===b.dataset.exactTeacherReport);if(o)teacherReport(o)});$$('[data-exact-teacher-message]',scope).forEach(b=>b.onclick=()=>{const o=teachers().find(x=>x.id===b.dataset.exactTeacherMessage);if(o)teacherMessageOpen(o)});$$('[data-exact-teacher-program]',scope).forEach(b=>b.onclick=()=>{const target=[...scope.querySelectorAll('[data-profile-section]')].find(x=>x.dataset.profileSection==='DERS PROGRAMI');target?.scrollIntoView({behavior:'smooth',block:'start'})});$$('[data-exact-teacher-leave-add]',scope).forEach(b=>b.onclick=()=>{closeDetail();global.AppLoader?.setActiveModule?.('management');global.AppLoader?.load?.('management').then(()=>global.ManagementModule?.openPage?.('dilekce','Dilekçe & İzinler')).catch(()=>global.toast?.('İzin ekranı açılamadı.'))});$$('[data-exact-club-list]',scope).forEach(b=>b.onclick=()=>global.PeopleImportUI?.printClubStudents?.(b.dataset.exactClubList));$$('[data-exact-doc-check]',scope).forEach(cb=>cb.onchange=async()=>{const old=!cb.checked;cb.disabled=true;try{await global.BelgeDurumuService?.kontrolKaydet?.(cb.dataset.teacherId,cb.dataset.docType,cb.dataset.docId,Number(cb.dataset.docIndex),cb.checked);cb.closest('.ka-teacher-doc-check')?.classList.toggle('is-complete',cb.checked)}catch(e){cb.checked=old;global.toast?.(e?.message==='kendi-belgesi'?'Kendi belge durumunuzu değiştiremezsiniz.':'Belge durumu güncellenemedi.')}finally{if(cb.isConnected&&!cb.closest('.is-readonly'))cb.disabled=false}});$$('[data-exact-class-edit]',scope).forEach(b=>b.onclick=e=>{e.stopPropagation();const id=b.dataset.exactClassEdit;closeDetail();classForm(id)});$$('[data-exact-student-edit]',scope).forEach(b=>b.onclick=e=>{e.stopPropagation();const id=b.dataset.exactStudentEdit;closeDetail();studentForm(id)});$$('[data-exact-class-tab]',scope).forEach(b=>b.onclick=()=>classDetail(b.dataset.classId,b.dataset.exactClassTab));$$('[data-exact-student-detail]',scope).forEach(b=>b.onclick=()=>studentDetail(b.dataset.exactStudentDetail));$$('[data-exact-student-add]',scope).forEach(b=>b.onclick=()=>studentForm('',b.dataset.exactStudentAdd||''));$$('[data-exact-class-excel]',scope).forEach(b=>b.onclick=()=>chooseExcel('student',b.dataset.exactClassExcel));$$('[data-exact-class-eokul]',scope).forEach(b=>b.onclick=()=>chooseEOkul(b.dataset.exactClassEokul));$$('[data-exact-class-list]',scope).forEach(b=>b.onclick=()=>openClassList(b.dataset.exactClassList));$$('[data-exact-class-seating]',scope).forEach(b=>b.onclick=()=>{closeDetail();openClassSeating(b.dataset.exactClassSeating)})}
function bind(){const search=$('[data-exact-search]',root);if(search)search.oninput=()=>{query=search.value;render()};const br=$('[data-exact-branch]',root);if(br)br.onchange=()=>{branch=br.value;render()};const sc=$('[data-exact-student-class]',root);if(sc)sc.onchange=()=>{studentClass=sc.value;render()};const sg=$('[data-exact-student-gender]',root);if(sg)sg.onchange=()=>{studentGender=sg.value;render()};$$('[data-exact-teacher-detail]',root).forEach(b=>b.onclick=()=>teacherDetail(b.dataset.exactTeacherDetail));$$('[data-exact-teacher-edit]',root).forEach(b=>b.onclick=()=>teacherForm(b.dataset.exactTeacherEdit));$('[data-exact-teacher-add]',root)?.addEventListener('click',()=>teacherForm());$('[data-exact-teacher-excel]',root)?.addEventListener('click',()=>chooseExcel('teacher'));$$('[data-exact-class-detail]',root).forEach(tr=>tr.onclick=e=>{if(e.target.closest('[data-exact-class-edit]'))return;classDetail(tr.dataset.exactClassDetail)});$$('[data-exact-class-edit]',root).forEach(b=>b.onclick=e=>{e.stopPropagation();classForm(b.dataset.exactClassEdit)});$('[data-exact-class-add]',root)?.addEventListener('click',()=>classForm());$('[data-exact-class-excel-all]',root)?.addEventListener('click',()=>chooseExcel('student',''));$('[data-exact-class-eokul-all]',root)?.addEventListener('click',()=>chooseEOkul(''));$$('[data-exact-student-detail]',root).forEach(b=>b.onclick=()=>studentDetail(b.dataset.exactStudentDetail));$('[data-exact-student-add]',root)?.addEventListener('click',()=>studentForm('',studentClass))}
function stopSubs(){unsubs.forEach(u=>{try{u()}catch(_){}});unsubs=[]}
function subscribe(){stopSubs();for(const p of ['data.ogretmenler','data.siniflar','data.veliler','data.servisler','data.dersProgrami','data.nobetAtamalari','data.nobetYerleri','data.sosyalKulupler','data.rehberlik','data.belirliGunler','data.bepPlani','data.zumre','data.sok','data.maarifRapor','data.ogretmenIzinleri','data.personelIzinler','data.digerEvrak']){const u=global.AppStore?.subscribe?.(p,()=>requestAnimationFrame(()=>{if(!detail&&!delegated)render()}));if(u)unsubs.push(u)}}
function mount(target=document.getElementById('v2ModuleRoot')){canonical.unmount?.();stopSubs();delegated=false;root=target;if(!root)return false;return true}
